import React, { useEffect, useState } from "react";
import axios from "axios";

function SmartPlanner() {
  const userId = localStorage.getItem("user_id");

  const [plans, setPlans] = useState([]);

  useEffect(() => {
    axios
      .get(`http://127.0.0.1:8000/smart-plan/${userId}`)
      .then((res) => setPlans(res.data.smart_plan))
      .catch((err) => console.error(err));
  }, [userId]);

  return (
    <div>
      <h2 style={{ color: "#7b1fa2" }}>Smart Study Planner 🧠</h2>

      {plans.length === 0 ? (
        <p>No data found</p>
      ) : (
        plans.map((p, index) => (
          <div key={index} style={card}>
            <h3>Course ID: {p.course_id}</h3>

            <p>Progress: {p.percentage}%</p>
            <p>
              Topics: {p.completed}/{p.total}
            </p>

            <h4 style={{ color: getColor(p.priority) }}>
              Priority: {p.priority}
            </h4>
          </div>
        ))
      )}
    </div>
  );
}

const getColor = (priority) => {
  if (priority.includes("High")) return "red";
  if (priority.includes("Medium")) return "orange";
  return "green";
};

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "12px",
  marginBottom: "15px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.1)"
};

export default SmartPlanner;
